/**
 * An editable diagram: what `/output/<name>.diagram.json` holds. The agent
 * writes it, the Diagram view draws and edits it, and every save is a new
 * version of the file. Kind 1 is a data model: entities, their fields, and the
 * relationships between them. Process flows come later on the same file.
 *
 * Shared with the server (scripts/sync-analyze-contract.mjs): the same review
 * runs when the agent saves the file and when the app reads it. Problems
 * refuse the file (it stays plain data); warnings keep it and are shown.
 */
import { z } from 'zod';
import type { Artifact } from '../../../types/notebook';

export const DIAGRAM_FILE_SUFFIX = '.diagram.json';

export const DATA_MODEL_PLATFORMS = ['salesforce', 'sql', 'generic'] as const;
export const RELATIONSHIP_KINDS = ['lookup', 'master_detail', 'foreign_key', 'conceptual'] as const;
/** The crow's-foot mark drawn at one end of a relationship line. */
export const CARDINALITIES = ['zero_or_one', 'exactly_one', 'zero_or_more', 'one_or_more'] as const;
/** The words a `source` can be instead of an input path. */
export const SOURCE_WORDS = ['platform', 'user', 'assumed'] as const;

export type DataModelPlatform = (typeof DATA_MODEL_PLATFORMS)[number];
export type RelationshipKind = (typeof RELATIONSHIP_KINDS)[number];
export type Cardinality = (typeof CARDINALITIES)[number];
export type SourceWord = (typeof SOURCE_WORDS)[number];

/** The relationship kinds each platform has. */
export const RELATIONSHIP_KINDS_BY_PLATFORM: Record<DataModelPlatform, readonly RelationshipKind[]> = {
  salesforce: ['lookup', 'master_detail', 'conceptual'],
  sql: ['foreign_key', 'conceptual'],
  generic: ['foreign_key', 'conceptual'],
};

const nameSchema = z.string().regex(/\S/, 'must not be blank');

const fieldSchema = z.object({
  /** Unique within its entity: `Center__c`, `center_id`. */
  name: nameSchema,
  label: z.string().optional(),
  /** As the platform writes it: `Text(80)`, `MasterDetail`, `varchar(255)`. */
  type: z.string().optional(),
  description: z.string().optional(),
  /** Picklist or enum values. */
  values: z.array(z.string()).optional(),
  primaryKey: z.boolean().optional(),
  required: z.boolean().optional(),
  unique: z.boolean().optional(),
  externalId: z.boolean().optional(),
  /** Where it came from; a field without one takes its entity's (sourceOf). */
  source: z.string().optional(),
});

const entitySchema = z.object({
  /** Never changes, even on a rename, so relationships, positions and version diffs hold. */
  id: nameSchema,
  /** What the platform calls it: `Enrollment__c`, `enrollments`, or "Enrollment". */
  name: nameSchema,
  label: z.string().optional(),
  description: z.string().optional(),
  source: z.string().optional(),
  fields: z.array(fieldSchema).default(() => []),
});

const relationshipSchema = z.object({
  id: nameSchema,
  kind: z.enum(RELATIONSHIP_KINDS),
  /** The entity that holds the field. */
  from: nameSchema,
  to: nameSchema,
  /** The field on `from` that holds the relationship; none for `conceptual`. */
  field: nameSchema.optional(),
  /** `foreign_key` only: the field on `to` it points at (default: the primary key). */
  toField: nameSchema.optional(),
  /** The mark drawn at each end: how many `from` per `to`, and how many `to` per `from`. */
  cardinality: z.object({ from: z.enum(CARDINALITIES), to: z.enum(CARDINALITIES) }),
  label: z.string().optional(),
});

const layoutSchema = z.object({
  /** Written by the editor. Positions for ids that no longer exist are ignored. */
  positions: z.record(z.string(), z.object({ x: z.number(), y: z.number() })).optional(),
});

const dataModelSchema = z.object({
  version: z.literal(1),
  kind: z.literal('data_model'),
  platform: z.enum(DATA_MODEL_PLATFORMS),
  title: nameSchema,
  summary: nameSchema,
  entities: z.array(entitySchema).default(() => []),
  relationships: z.array(relationshipSchema).default(() => []),
  layout: layoutSchema.optional(),
});

export const diagramFileSchema = z.discriminatedUnion('kind', [dataModelSchema], {
  // Zod's own words for an unknown kind are "Invalid input".
  error: (issue) => (issue.code === 'invalid_union' ? 'expected "data_model"' : undefined),
});

export type DiagramFileV1 = z.infer<typeof diagramFileSchema>;
export type DataModelDiagram = z.infer<typeof dataModelSchema>;
export type DataModelEntity = z.infer<typeof entitySchema>;
export type DataModelField = z.infer<typeof fieldSchema>;
export type DataModelRelationship = z.infer<typeof relationshipSchema>;
export type DiagramLayout = z.infer<typeof layoutSchema>;

export type DiagramSource =
  | { kind: 'file'; path: string; entry?: string }
  | { kind: SourceWord };

export interface DiagramReview {
  /** The diagram, or null when a problem refuses it. */
  diagram: DiagramFileV1 | null;
  /** Why the file is refused. */
  problems: string[];
  /** What the file keeps but should fix. */
  warnings: string[];
}

export type DiagramMetadata = NonNullable<NonNullable<Artifact['metadata']>['diagram']>;

/** metadata.diagram for a diagram the review kept: what the Outputs list shows without reading the file. */
export function diagramMetadata(diagram: DiagramFileV1, warnings: string[], savedByUser = false): DiagramMetadata {
  return {
    kind: diagram.kind,
    title: diagram.title,
    summary: diagram.summary,
    entityCount: diagram.entities.length,
    relationshipCount: diagram.relationships.length,
    ...(warnings.length > 0 ? { warnings } : {}),
    ...(savedByUser ? { savedByUser: true } : {}),
  };
}

/** The file's text for a diagram the app writes (a hand save): indented, so it reads as a file. */
export function diagramFileText(diagram: DiagramFileV1): string {
  return `${JSON.stringify(diagram, null, 2)}\n`;
}

/** Whether this /output path is a diagram file (`<name>.diagram.json`). */
export function isDiagramFilename(filename: string): boolean {
  const base = filename.slice(filename.lastIndexOf('/') + 1).toLowerCase();
  return base.length > DIAGRAM_FILE_SUFFIX.length && base.endsWith(DIAGRAM_FILE_SUFFIX);
}

/**
 * A `source` string read: an input path with an optional `#` and the entry or
 * line inside it (`/uploads/metadata.zip#objects/…`, `/uploads/schema.sql#L42`),
 * or one of SOURCE_WORDS. Null when it's missing or neither.
 */
export function parseDiagramSource(source: string | undefined): DiagramSource | null {
  if (!source) return null;
  if ((SOURCE_WORDS as readonly string[]).includes(source)) return { kind: source as SourceWord };
  if (!source.startsWith('/') || source.length < 2) return null;
  const hash = source.indexOf('#');
  if (hash < 0) return { kind: 'file', path: source };
  const path = source.slice(0, hash);
  const entry = source.slice(hash + 1);
  return entry ? { kind: 'file', path, entry } : { kind: 'file', path };
}

/** Where a field (or, with no field, the entity) came from: a field without a source takes its entity's. */
export function sourceOf(entity: DataModelEntity, field?: DataModelField): string | undefined {
  return field?.source ?? entity.source;
}

/** The review of a diagram file's text. */
export function reviewDiagramText(text: string): DiagramReview {
  let candidate: unknown;
  try {
    candidate = JSON.parse(text);
  } catch (error) {
    return { diagram: null, problems: [`it isn't valid JSON (${error instanceof Error ? error.message : String(error)})`], warnings: [] };
  }
  return reviewDiagram(candidate);
}

/** The review of a parsed diagram file: its shape, then what the shape can't say. */
export function reviewDiagram(candidate: unknown): DiagramReview {
  const parsed = diagramFileSchema.safeParse(candidate);
  if (!parsed.success) {
    const problems = parsed.error.issues.map((issue) => `${issue.path.length > 0 ? issue.path.join('.') : '(top level)'}: ${issue.message}`);
    return { diagram: null, problems, warnings: [] };
  }
  const { problems, warnings } = reviewDataModel(parsed.data);
  return { diagram: problems.length > 0 ? null : parsed.data, problems, warnings };
}

/** The diagram, or null when the text isn't a usable diagram file. */
export function parseDiagramFile(text: string): DiagramFileV1 | null {
  return reviewDiagramText(text).diagram;
}

function isMany(cardinality: Cardinality): boolean {
  return cardinality === 'zero_or_more' || cardinality === 'one_or_more';
}

function reviewDataModel(diagram: DataModelDiagram): { problems: string[]; warnings: string[] } {
  const problems: string[] = [];
  const warnings: string[] = [];
  const checkSource = (source: string | undefined, where: string) => {
    if (source !== undefined && parseDiagramSource(source) === null) {
      warnings.push(`${where}: source "${source}" is neither an input path (/uploads/…) nor platform, user or assumed`);
    }
  };

  const entities = new Map<string, DataModelEntity>();
  for (const entity of diagram.entities) {
    if (entities.has(entity.id)) problems.push(`two entities have the id "${entity.id}"`);
    else entities.set(entity.id, entity);
    checkSource(entity.source, `entity "${entity.id}"`);
    const fieldNames = new Set<string>();
    for (const field of entity.fields) {
      if (fieldNames.has(field.name)) problems.push(`entity "${entity.id}" has two fields named "${field.name}"`);
      fieldNames.add(field.name);
      checkSource(field.source, `field "${entity.id}.${field.name}"`);
    }
  }

  const allowedKinds = RELATIONSHIP_KINDS_BY_PLATFORM[diagram.platform];
  const relationshipIds = new Set<string>();
  const masterDetails = new Map<string, number>();
  for (const relationship of diagram.relationships) {
    const where = `relationship "${relationship.id}"`;
    const { kind, cardinality } = relationship;
    if (relationshipIds.has(relationship.id)) problems.push(`two relationships have the id "${relationship.id}"`);
    relationshipIds.add(relationship.id);
    if (!allowedKinds.includes(kind)) {
      problems.push(`${where}: a ${diagram.platform} model has no ${kind} relationships (it has ${allowedKinds.join(', ')})`);
    }
    const from = entities.get(relationship.from);
    const to = entities.get(relationship.to);
    if (!from) problems.push(`${where}: from "${relationship.from}" isn't an entity id`);
    if (!to) problems.push(`${where}: to "${relationship.to}" isn't an entity id`);
    if (relationship.toField !== undefined && kind !== 'foreign_key') {
      problems.push(`${where}: toField is for foreign_key relationships only`);
    }

    if (kind === 'conceptual') {
      if (relationship.field !== undefined) {
        problems.push(`${where}: a conceptual relationship has no field; a relationship a field holds is ${allowedKinds.filter((k) => k !== 'conceptual').join(' or ')}`);
      }
      continue;
    }

    if (isMany(cardinality.to)) {
      problems.push(`${where}: its to end is ${cardinality.to}, but a field holds at most one "${relationship.to}"; use zero_or_one or exactly_one, or a junction entity for many-to-many`);
    }
    if (relationship.field === undefined) {
      problems.push(`${where}: a ${kind} relationship needs field, the field on "${relationship.from}" that holds it`);
      continue;
    }
    const field = from?.fields.find((candidate) => candidate.name === relationship.field);
    if (from && !field) problems.push(`${where}: "${relationship.from}" has no field "${relationship.field}"`);
    if (to && relationship.toField !== undefined && !to.fields.some((candidate) => candidate.name === relationship.toField)) {
      problems.push(`${where}: "${relationship.to}" has no field "${relationship.toField}"`);
    }

    const fieldName = `"${relationship.from}.${relationship.field}"`;
    if (kind === 'master_detail') {
      masterDetails.set(relationship.from, (masterDetails.get(relationship.from) ?? 0) + 1);
      // A master-detail field is always required, whatever its flag says.
      if (cardinality.to === 'zero_or_one') {
        warnings.push(`${where}: a master-detail's to end is exactly_one (every detail has a master), not zero_or_one`);
      }
    } else if (field && !isMany(cardinality.to)) {
      const lineRequires = cardinality.to === 'exactly_one';
      if (field.required && !lineRequires) {
        warnings.push(`${where}: ${fieldName} is required, but the to end is ${cardinality.to}; make the end exactly_one, or the field optional`);
      } else if (!field.required && lineRequires) {
        warnings.push(`${where}: the to end is exactly_one, but ${fieldName} isn't required; mark the field required, or make the end zero_or_one`);
      }
    }
    if (field?.unique && isMany(cardinality.from)) {
      warnings.push(`${where}: ${fieldName} is unique, so one "${relationship.to}" has at most one "${relationship.from}", but the from end is ${cardinality.from}; use zero_or_one or exactly_one`);
    }
  }

  if (diagram.platform === 'salesforce') {
    for (const [entityId, count] of masterDetails) {
      if (count > 2) warnings.push(`entity "${entityId}" has ${count} master-detail relationships; Salesforce allows two per object`);
    }
  }

  return { problems, warnings };
}
